 async function removeStore(){const target=editingStore,context=contextRef.current;if(!target||!context)return;const fallback=data.stores.find(s=>s.id!==target.id);if(!fallback){notify('Serve almeno un negozio');return}if(!window.confirm(`Eliminare "${target.name}"? Si perdono il percorso dei reparti e i prezzi salvati per questo negozio.`))return;setBusyAction(true);try{await saveQueueRef.current.catch(()=>undefined);if(dataRef.current!==lastPersistedRef.current)throw new Error('Sincronizza le modifiche prima di eliminare il negozio.');setSyncState('saving');const next=await deleteStore(supabase,context.familyId,dataRef.current,target.id,fallback.id);replaceData(next);setSyncState('saved');setModal(null);notify('Negozio eliminato')}catch(error){setSyncState('error');setAppError(errorText(error)||'Non riesco a eliminare il negozio.');notify(errorText(error)||'Non riesco a eliminare il negozio.')}finally{setBusyAction(false)}}
 function openProduct(p?:Product){setEditing(p??null);setForm(p?{name:p.name,category:p.category,qty:p.qty,note:p.note,barcode:p.barcode,price:String(p.prices[store?.id??'']??'')}:{name:'',category:'Ortofrutta',qty:'1',note:'',barcode:'',price:''});setModal('product')}
 function saveProduct(){if(!form.name.trim())return;const price=Number(form.price.replace(',','.')), qty=packageCount(form.qty);if(editing){setData({...data,products:data.products.map(p=>p.id===editing.id?{...p,name:form.name.trim(),category:form.category,qty,note:form.note,barcode:form.barcode,prices:{...p.prices,...(price>0&&store?{[store.id]:price}:{})}}:p),stores:data.stores.map(s=>({...s,order:insertDept(s.order,form.category)}))});notify('Prodotto aggiornato')}else{const id=crypto.randomUUID();const p:Product={id,name:form.name.trim(),category:form.category,emoji:iconFor(form.category),qty,note:form.note,barcode:form.barcode,prices:price>0&&store?{[store.id]:price}:{}};const addNow=fromPicker&&!!data.trip;setData({...data,products:[p,...data.products],stores:data.stores.map(s=>({...s,order:insertDept(s.order,form.category)})),trip:addNow&&data.trip?{...data.trip,items:[...data.trip.items,{productId:id,qty,checked:false}]}:data.trip});notify(addNow?`${p.name} aggiunto alla spesa`:'Aggiunto alla lista di casa')}setModal(fromPicker&&!editing?'picker':null);setPickerQuery('');setFromPicker(false)}
 function addStore(){if(!newStore.trim())return;if(data.stores.some(s=>s.name.toLowerCase()===newStore.trim().toLowerCase())){notify('Esiste già un negozio con questo nome');return}const id=crypto.randomUUID();setData({...data,stores:[...data.stores,{id,name:newStore.trim(),color:'#7c68b1',order:flatDepartments(data)}]});setNewStore('');setModal(null);notify('Negozio creato')}
 function openList(id: string) {
   setData(current => preferredStore
     ? assignListStore(current, id, familyId, preferredStore)
     : chooseList(current, id, familyId));
   setPreferredStore(undefined);
   setShowLists(false);
   setTab('spesa');
 }
 async function createList(name: string) {
   const current = dataRef.current;
   if (name.toLocaleLowerCase('it') === GENERAL.toLocaleLowerCase('it') ||
       current.lists?.some(list => list.name.toLocaleLowerCase('it') === name.toLocaleLowerCase('it'))) {
     throw new Error('Esiste già una lista con questo nome.');
   }
   const id = await namedListId(familyId, name);
   setData(latest => {
     const lists = latest.lists ?? [];
     if (lists.some(list => list.id === id)) return latest;
     return { ...latest, lists: [...lists, { id, name, items: [] }] };
   });
   openList(id);
 }
 async function deleteList(id: string) {
   if (id === familyId) return;
   await saveQueueRef.current;
   if (dataRef.current !== lastPersistedRef.current) {
     throw new Error('Attendi la sincronizzazione prima di eliminare la lista.');
   }
   const { error } = await supabase.from('shopping_lists').delete()
     .eq('family_id', familyId).eq('id', id).eq('status', 'active');
   if (error) throw new Error(error.message);
   const current = dataRef.current;
   const next = { ...current, lists: current.lists?.filter(list => list.id !== id) };
   replaceData(current.trip?.id && current.trip.id !== id
     ? chooseList(next, current.trip.id, familyId)
     : { ...next, trip: null });
 }
 function startTrip(storeId: string) {
   setPreferredStore(storeId);
   setShowLists(true);
 }
 function selectStore(storeId: string) {
   const selectedId = dataRef.current.trip?.id;
   if (selectedId) setData(current => assignListStore(current, selectedId, familyId, storeId));
 }

 function reorder(cat:string,dir:number){if(!store)return;const at=store.order.indexOf(cat),to=at+dir;if(to<0||to>=store.order.length)return;const order=[...store.order];[order[at],order[to]]=[order[to],order[at]];setData({...data,stores:data.stores.map(s=>s.id===store.id?{...s,order}:s)});notify('Percorso aggiornato per '+store.name)}
 function moveCategory(storeId:string,from:string,to:string){setData(current=>({...current,stores:current.stores.map(s=>{if(s.id!==storeId)return s;const order=[...s.order],a=order.indexOf(from),b=order.indexOf(to);if(a<0||b<0||a===b)return s;order.splice(a,1);order.splice(b,0,from);return {...s,order}})}));}
